export function createClassifierScratchRoot() {
  const root = mkdtempSync(join(tmpdir(), "omnimind-classifier-"));
  chmodSync(root, 0o700);
  return root;
}

let cachedScratchRoot: string | null = null;
export function createClassifierScratchRoot() {
  if (cachedScratchRoot === null) cachedScratchRoot = mkdtempSync(join(tmpdir(), "omnimind-classifier-"));
  chmodSync(cachedScratchRoot, 0o700);
  return cachedScratchRoot;
}
